import{_ as a,o,c as t,ak as d}from"./chunks/framework.DxrHb2fb.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1790413717000}'),c={name:"faq.md"};function r(n,e,i,s,l,p){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="与-xihan-basicapp-的前端是什么关系" tabindex="-1">与 XiHan.BasicApp 的前端是什么关系 <a class="header-anchor" href="#与-xihan-basicapp-的前端是什么关系" aria-label="Permalink to &quot;与 XiHan.BasicApp 的前端是什么关系&quot;">​</a></h2><p>BasicApp 的前端构建于 XiHan.UI 之上：自 BasicApp v4.0.0 起，它的前端整体使用本库重建。了解组件库在真实业务中的用法，可以阅读 BasicApp 前端的源码。</p><p>BasicApp 的前端约定见<a href="https://basicapp.docs.xihanfun.com/frontend/introduction" target="_blank" rel="noreferrer">基础应用前端手册</a>。</p><h2 id="共有多少个组件" tabindex="-1">共有多少个组件 <a class="header-anchor" href="#共有多少个组件" aria-label="Permalink to &quot;共有多少个组件&quot;">​</a></h2><p>136 个。每个组件同时有无头内核、Vue / React 组件、自定义元素与默认皮肤。<a href="./components/">组件总览</a>按分类列出全部组件，每个组件一页。</p><h2 id="组件的-props-在哪里查看" tabindex="-1">组件的 props 在哪里查看 <a class="header-anchor" href="#组件的-props-在哪里查看" aria-label="Permalink to &quot;组件的 props 在哪里查看&quot;">​</a></h2><p>以 TypeScript 类型为准。<code>@xihan-ui/headless</code> 为每个组件导出 <code>XxxSchema</code>（含 <code>props</code>、<code>context</code>、<code>event</code> 等）与 <code>XxxApi</code>，编辑器可以直接跳转，注释也在类型上。</p><p>文档侧给出的是结构契约（解剖部件、必备部件、键盘表），这部分无法从类型中直接读出。两者配合查看。</p><h2 id="可以不使用默认皮肤吗" tabindex="-1">可以不使用默认皮肤吗 <a class="header-anchor" href="#可以不使用默认皮肤吗" aria-label="Permalink to &quot;可以不使用默认皮肤吗&quot;">​</a></h2><p>可以，这是设计上支持的用法。组件只向 DOM 写入 <code>data-scope</code> / <code>data-part</code> / <code>data-state</code> 等属性，不依赖 <code>@xihan-ui/styles</code> 的任何规则。</p><p>只引入令牌自行编写皮肤，或连令牌一起移除，都可以。见<a href="./guide/styling#完全自定义皮肤">皮肤与样式分层</a>。</p><h2 id="是否支持-react-svelte-solid" tabindex="-1">是否支持 React / Svelte / Solid <a class="header-anchor" href="#是否支持-react-svelte-solid" aria-label="Permalink to &quot;是否支持 React / Svelte / Solid&quot;">​</a></h2><p>目前提供 Vue、React 与 Web Components 三个适配器。</p><p>自定义元素在各框架中都可以直接使用（Light DOM，无 Shadow DOM 封装），这是通用路径。编写原生适配器需要三个部分：一份 <code>ReactiveRuntime</code>（五个接口）、一份 <code>NormalizeProps</code>、一层组件包装。<code>@xihan-ui/core/vanilla</code> 是这套契约的参考实现。</p><h2 id="自定义元素为什么需要自行编写-html" tabindex="-1">自定义元素为什么需要自行编写 HTML <a class="header-anchor" href="#自定义元素为什么需要自行编写-html" aria-label="Permalink to &quot;自定义元素为什么需要自行编写 HTML&quot;">​</a></h2><p>因为它是 Light DOM 行为宿主，不是 Shadow DOM 组件。Shadow DOM 会封闭结构：无法更换标签、无法插入自定义节点、外部 CSS 无法进入、表单关联与跨边界 <code>aria-*</code> 引用都需要额外机制。本库的定位是行为可复用、外观完全由使用者决定。</p><p>代价是需要编写结构。缺少必备部件不会静默失败，诊断通道会明确报告。见 <a href="./adapters/web-components">Web Components 适配器</a>。</p><h2 id="切换品牌为什么没有效果" tabindex="-1">切换品牌为什么没有效果 <a class="header-anchor" href="#切换品牌为什么没有效果" aria-label="Permalink to &quot;切换品牌为什么没有效果&quot;">​</a></h2><p>品牌轴需要注册后才会换色：<code>registerBrand(id, 种子色)</code> 注入该 id 的原语取值块，切换到该品牌才有视觉变化；不注册只会把 <code>data-brand</code> 写到 DOM 上。</p><p>明暗、对比度、密度、书写方向四条轴默认即有取值，切换即生效。见<a href="./guide/theme#八轴视觉环境运行时">设计令牌与主题</a>。</p><h2 id="皮肤中的某条样式未生效" tabindex="-1">皮肤中的某条样式未生效 <a class="header-anchor" href="#皮肤中的某条样式未生效" aria-label="Permalink to &quot;皮肤中的某条样式未生效&quot;">​</a></h2><p>先检查是否引用了不存在的令牌名。孤儿引用不报错也不降级，整条声明在计算值阶段静默失效。仓库中的 <code>check-token-refs</code> 门禁专门检查这一点。</p><p>其次检查层序：按组件引入样式时必须先引入 <code>@xihan-ui/styles/layers.css</code> 或 <code>@xihan-ui/tokens/tokens.css</code> 之一（两者都带完整层序声明），否则级联顺序会退化为引入顺序。</p><h2 id="浮层位置整体偏移了一个滚动距离" tabindex="-1">浮层位置整体偏移了一个滚动距离 <a class="header-anchor" href="#浮层位置整体偏移了一个滚动距离" aria-label="Permalink to &quot;浮层位置整体偏移了一个滚动距离&quot;">​</a></h2><p>坐标系不一致。状态机传给定位引擎的 <code>strategy</code>、<code>connect</code> 产出的内联 <code>position</code>、皮肤中 <code>positioner</code> 规则的 <code>position</code>，三处必须为同一个值。</p><p><code>check-overlay-strategy</code> 门禁检查这三处，但只覆盖登记在名单中的浮层组件。见<a href="./guide/position#两套坐标系">浮层定位</a>。</p><h2 id="受控组件点击后没有反应" tabindex="-1">受控组件点击后没有反应 <a class="header-anchor" href="#受控组件点击后没有反应" aria-label="Permalink to &quot;受控组件点击后没有反应&quot;">​</a></h2><p>这是预期行为。受控时组件不会自行改变：它只发出变更意图（<code>value-change</code> / <code>open-change</code>），由使用者写回新值后才真正改变。</p><p>传入受控属性就必须处理变更事件并写回。只需要初值、不需要管理后续时，使用 <code>default*</code> 走非受控。</p><h2 id="关闭浮层时退场动画未播完就消失" tabindex="-1">关闭浮层时退场动画未播完就消失 <a class="header-anchor" href="#关闭浮层时退场动画未播完就消失" aria-label="Permalink to &quot;关闭浮层时退场动画未播完就消失&quot;">​</a></h2><p>检查 <code>data-state</code> 的提交时机。适配器必须在 <code>data-state</code> 已提交到 DOM 之后才通知进出场原语：先改属性再让 CSS 过渡启动，顺序相反时动画不会播放。</p><p>使用现成组件时这一条已经接好；自行使用 <code>api</code> 渲染时需要注意。</p><h2 id="生产环境看不到诊断信息" tabindex="-1">生产环境看不到诊断信息 <a class="header-anchor" href="#生产环境看不到诊断信息" aria-label="Permalink to &quot;生产环境看不到诊断信息&quot;">​</a></h2><p>默认如此。生产环境诊断阈值是 <code>silent</code>，投递直接丢弃，不产生开销。</p><p>需要在生产环境收集时，显式调用 <code>setDiagnosticsLevel(&#39;error&#39;)</code> 并挂载自己的订阅。见<a href="./guide/diagnostics">诊断通道</a>。</p><h2 id="如何新增组件" tabindex="-1">如何新增组件 <a class="header-anchor" href="#如何新增组件" aria-label="Permalink to &quot;如何新增组件&quot;">​</a></h2><p>四份产物一起新增，缺一份即未完成：</p><ol><li><code>packages/engine/headless/src/&lt;name&gt;/</code>：解剖、状态机、<code>connect</code>、键盘规格表、元数据；</li><li><code>packages/adapters/vue/src/components/&lt;name&gt;/</code>：组件与组合式函数；</li><li><code>packages/adapters/web-components/src/elements/&lt;name&gt;.ts</code>：自定义元素，并在 <code>define.ts</code> 注册；</li><li><code>packages/design/styles/css/&lt;name&gt;.css</code>：皮肤，并在 <code>index.css</code> 引入。</li></ol><p>然后补充一致性套件（<code>tooling/testing/src/suites/&lt;name&gt;.suite.ts</code>），运行 <code>pnpm test</code>、<code>pnpm test:browser</code>、<code>pnpm gate</code>、<code>pnpm boundaries</code>、<code>pnpm gate:cem</code>。</p><p>键盘规格表是先行确立的契约：用例通过 <code>covers</code> 反查行 id，缺一行即套件失败。</p><h2 id="无障碍问题何时修复" tabindex="-1">无障碍问题何时修复 <a class="header-anchor" href="#无障碍问题何时修复" aria-label="Permalink to &quot;无障碍问题何时修复&quot;">​</a></h2><p>没有承诺的时间表。当前状态记录在<a href="./guide/a11y#存量违规登记表">无障碍与键盘规格</a>：共用表中 tag 一条、WC 侧 steps 一条，全局登记表为空，另有 breadcrumb 一条步骤重放豁免。</p><p>登记表有一条自净规则：一条都不再命中时判定登记过期，修复后必须从表中删除。</p><h2 id="如何让-ai-正确编写本库的代码" tabindex="-1">如何让 AI 正确编写本库的代码 <a class="header-anchor" href="#如何让-ai-正确编写本库的代码" aria-label="Permalink to &quot;如何让 AI 正确编写本库的代码&quot;">​</a></h2><p>模型没有见过这套契约，凭印象编写的代码多数是 React 生态的写法：给组件传 <code>class</code>、用 <code>color</code> 作为形态 prop、样式中写死颜色与时长。提供以下文件即可，它们由文档站构建期生成，与库同源：</p><table tabindex="0"><thead><tr><th>地址</th><th>内容</th></tr></thead><tbody><tr><td><a href="https://ui.docs.xihanfun.com/llms.txt" target="_blank" rel="noreferrer"><code>/llms.txt</code></a></td><td>全站索引，每行一页</td></tr><tr><td><a href="https://ui.docs.xihanfun.com/llms-components.txt" target="_blank" rel="noreferrer"><code>/llms-components.txt</code></a></td><td>全部组件参考页</td></tr><tr><td><a href="https://ui.docs.xihanfun.com/llms-guide.txt" target="_blank" rel="noreferrer"><code>/llms-guide.txt</code></a></td><td>核心概念、适配器与运行时</td></tr><tr><td><a href="https://ui.docs.xihanfun.com/llms-tokens.txt" target="_blank" rel="noreferrer"><code>/llms-tokens.txt</code></a></td><td>令牌全表：名称、类型、默认取值</td></tr></tbody></table><p>只需要一页时，把地址后缀改为 <code>.md</code>：<code>https://ui.docs.xihanfun.com/components/button.md</code> 即按钮页，示例已内联为代码块。每页正文右上角的“取本页 Markdown”指向的也是它。</p><p>支持 Agent Skills 的工具可以直接读取仓库根的 <code>.agents/skills/</code>：<a href="https://ui.docs.xihanfun.com/skills/component-design/SKILL.md" target="_blank" rel="noreferrer"><code>component-design</code></a> 负责设计与视觉，<a href="https://ui.docs.xihanfun.com/skills/component-development/SKILL.md" target="_blank" rel="noreferrer"><code>component-development</code></a> 负责实现与仓库流程，<a href="https://ui.docs.xihanfun.com/skills/framework-adapters/SKILL.md" target="_blank" rel="noreferrer"><code>framework-adapters</code></a> 负责三端接法。开发技能提供四个只读脚本；脚本严格读取当前检出，找不到仓库时直接报错，不使用已发布站点的内容代替本地事实。</p><h2 id="其他问题" tabindex="-1">其他问题 <a class="header-anchor" href="#其他问题" aria-label="Permalink to &quot;其他问题&quot;">​</a></h2><ul><li>源码仓库：<a href="https://github.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://gitee.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">Gitee</a> · <a href="https://gitcode.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">GitCode</a></li><li>文档站的组件示例覆盖全部 136 个组件，Vue、React 与自定义元素的写法并排，行为问题优先在那里复现</li></ul>',51)])])}const m=a(c,[["render",r]]);export{u as __pageData,m as default};
